"""Compact offline report of completed v2 runs; missing artifacts stay pending."""
from __future__ import annotations
import argparse
import csv
from copy import deepcopy
import hashlib
import json
from pathlib import Path

from benchmarks.render_report import CSS
from benchmarks.metrics import metrics_for_query

ROOT=Path(__file__).resolve().parents[1]


def optional(path):
    if not path.exists():return None
    value=json.loads(path.read_text())
    return None if isinstance(value,dict) and value.get('status') in {'pending','running','partial','failed'} else value


def compact(value):
    """Never embed huge rankings/checkpoints; raw JSON downloads preserve them."""
    if isinstance(value,dict):return {key:compact(item) for key,item in value.items() if key not in {'rankings','gated_rankings','per_query','calibration_grid','queries','query_checks'}}
    if isinstance(value,list):return [compact(item) for item in value]
    return value


def collect(directory):
    originals={name:optional(directory/f'{name}-results.json') for name in ('index','cross-domain','rerank','temporal')}
    data={name:compact(value) if value else None for name,value in originals.items()}
    data['hashes']={f'{name}-results.json':hashlib.sha256((directory/f'{name}-results.json').read_bytes()).hexdigest() for name,value in originals.items() if value}
    for name,filename in [('optimization','optimization-results.json'),('lexical-optimization','lexical-optimization-results.json'),('token-pilot','token-postings-pilot.json')]:
        value=optional(directory/filename)
        data[name]=compact(value) if value else None
        if value:data['hashes'][filename]=hashlib.sha256((directory/filename).read_bytes()).hexdigest()
    data['temporal_examples']=[];data['rerank_examples']=[]
    fixture=optional(ROOT/'benchmarks/data/temporal-v2.json')
    if originals['temporal'] and fixture:
        result=originals['temporal'];method='Chronoverse actual Store';run=result['systems'][method];by_id={row['id']:row for row in fixture['assertions']}
        groups={}
        for query in result['queries']:
            if query['split']!='test':continue
            old=run['rankings'][query['id']];new=run['gated_rankings'][query['id']];gold=set(query['gold_assertion_ids'])
            kind='Lost relevant support' if gold-set(new) else 'Empty target still answered' if not gold and new else 'Correct empty abstention' if not gold else 'Retained relevant support'
            key=(kind,query['family'])
            groups.setdefault(key,{**query,'kind':kind,'before':old[:10],'after':new[:10]})
        priority={'Lost relevant support':0,'Empty target still answered':1,'Correct empty abstention':2,'Retained relevant support':3}
        selected=sorted(groups.values(),key=lambda q:(priority[q['kind']],q['family'],q['id']))[:12]
        needed={aid for q in selected for aid in q['before']+q['after']+q['gold_assertion_ids']}
        data['temporal_examples']=selected
        data['temporal_record_labels']={aid:f"{by_id[aid]['subject']} → {by_id[aid]['predicate']} → {by_id[aid]['object']}" for aid in needed}
    if originals['rerank']:
        qrels={};qpath=ROOT/'.benchmark-data/scifact/qrels/test.tsv'
        if qpath.exists():
            with qpath.open() as source:
                for row in csv.DictReader(source,delimiter='\t'):
                    if int(row['score'])>0:qrels.setdefault(row['query-id'],{})[row['corpus-id']]=int(row['score'])
        candidates=[]
        for row in originals['rerank']['per_query']:
            if row['id'] not in qrels:continue
            before=metrics_for_query(row['candidates'],qrels[row['id']]);after=metrics_for_query(row['reranked'],qrels[row['id']])
            candidates.append(dict(id=row['id'],query=row['query'],gold=list(qrels[row['id']]),before=row['candidates'][:10],after=row['reranked'][:10],before_metrics=before,after_metrics=after,delta=after['ndcg@10']-before['ndcg@10']))
        losses=sorted([row for row in candidates if row['delta']<0],key=lambda row:(row['delta'],row['id']))[:5]
        gains=sorted([row for row in candidates if row['delta']>0],key=lambda row:(-row['delta'],row['id']))[:5]
        data['rerank_examples']=losses+gains
        needed={aid for row in losses+gains for aid in row['before']+row['after']+row['gold']}
        titles={};cpath=ROOT/'.benchmark-data/scifact/corpus.jsonl'
        if cpath.exists():
            with cpath.open() as source:
                for line in source:
                    row=json.loads(line)
                    if row['_id'] in needed:titles[row['_id']]=row['title']
        data['rerank_titles']=titles
    return data


