JS=r'''
const D=JSON.parse(document.getElementById('data').textContent);let track='index',dataset='',split='test',mode='gated';
const $=id=>document.getElementById(id),e=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const f=(value,d=4)=>Number.isFinite(value)?value.toFixed(d):'—',p=value=>Number.isFinite(value)?(100*value).toFixed(1)+'%':'—',ms=value=>Number.isFinite(value)?(value*1000).toFixed(2)+' ms':'—',sec=value=>Number.isFinite(value)?value.toFixed(2)+' s':'—';
const names={bm25:'BM25',minilm_dense:'MiniLM dense',bge_dense:'BGE dense',minilm_hybrid_rrf:'BM25 + MiniLM RRF',bge_hybrid_rrf:'BM25 + BGE RRF',three_way_rrf:'BM25 + MiniLM + BGE RRF',rrf_minilm_top50:'RRF · fixed top-50 pool',rrf_minilm_cross_encoder:'RRF + cross-encoder'};
const name=value=>value==='rrf_minilm_cross_encoder'&&D.rerank?.parameters?.runtime?`RRF + cross-encoder (${D.rerank.parameters.runtime})`:names[value]||value;
function card(title,value,note){return `<div class="card"><span>${e(title)}</span><strong>${e(value)}</strong><small>${e(note)}</small></div>`;}
function raw(title,value){return `<details class="protocol-details"><summary>${e(title)}</summary><pre>${e(JSON.stringify(value,null,2))}</pre></details>`;}
function pending(title,file){return `<div class="pending"><h3>${e(title)} is pending</h3><p>No completed <code>${e(file)}</code> was present at report generation. Partial checkpoints and pilot timings are not substituted for final results.</p><p>Regenerate this local report when the recorded run completes.</p></div>`;}
function heading(title,text,file){return `<div class="track-title"><div><h2>${e(title)}</h2><p class="track-subtitle">${e(text)}</p></div><a href="${e(file)}" download class="download">↓ Raw results JSON</a></div>`;}
function table(rows,keys,labels={}){return `<div class="table-wrap"><table><thead><tr><th>Method / phase</th>${keys.map(k=>`<th class="number">${e(labels[k]||k)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr class="${row.name.includes('Chronoverse')?'chrono':''}"><td>${e(name(row.name))}</td>${keys.map(k=>`<td class="number">${f(row.metrics?.[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function bars(rows,key){return `<div class="bar-chart">${[...rows].sort((a,b)=>(b.metrics[key]||0)-(a.metrics[key]||0)).map(row=>`<div class="bar-row ${row.name.includes('Chronoverse')?'chrono':''}"><div class="bar-label">${e(name(row.name))}</div><div class="bar-track" role="img" aria-label="${e(name(row.name))} ${e(key)} ${f(row.metrics[key])}"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,100*(row.metrics[key]||0)))}%"></div></div><span class="bar-value">${f(row.metrics[key])}</span></div>`).join('')}</div><div class="bar-axis"><span>0</span><span>.25</span><span>.50</span><span>.75</span><span>1</span></div>`;}
function optimizationView(){
 const stages=[['optimization','Clock normalization + bulk event projection'],['lexical-optimization','Bounded lexical postings + bulk event projection']];
 const measured=stages.filter(([key])=>D[key]);
 let html=`<section class="panel"><h3>Subsequent production optimizations</h3><p class="subtext">These are separate full-query runs after the original persistence experiment. The original index result is preserved above.</p>`;
 if(measured.length){html+=`<div class="table-wrap"><table><thead><tr><th>Recorded stage</th><th class="number">Queries</th><th class="number">Warm p50</th><th class="number">Warm p95</th><th class="number">nDCG@10</th><th class="number">Identical IDs + scores</th></tr></thead><tbody>${measured.map(([key,title])=>{const row=D[key];return `<tr><td>${e(title)}</td><td class="number">${e(row.test_query_count)}</td><td class="number">${ms(row.warm_latency?.p50_seconds)}</td><td class="number">${ms(row.warm_latency?.p95_seconds)}</td><td class="number">${f(row.metrics?.['ndcg@10'])}</td><td class="number">${e(row.preservation?.identical_ids_and_scores??'—')} / ${e(row.preservation?.compared_queries??'—')}</td></tr>`;}).join('')}</tbody></table></div>`;}
 for(const [key,title] of stages){const row=D[key];html+=row?`<details class="protocol-details"><summary>${e(title)} · protocol and preservation</summary><p class="subtext">${e(row.change)}</p><p>First reopened query: ${sec(row.cold_reopened_query?.seconds)}.</p><ul class="caveats">${(row.limitations||[]).map(x=>`<li>${e(x)}</li>`).join('')}</ul><pre>${e(JSON.stringify(row,null,2))}</pre><a href="${e(key)}-results.json" download>↓ Full stage JSON</a></details>`:`<p class="subtext">${e(title)}: pending completed <code>${e(key)}-results.json</code>.</p>`;}
 html+=`<div class="notice"><strong>Historical timings on a shared machine are descriptive.</strong> CPU contention and model state changed between runs. These measurements do not isolate a causal speedup, and the lexical-only pilot below is not full Store latency. SciFact has no lifecycle events; temporal regression tests cover event projection separately.</div><p class="report-methods"><a href="OPTIMIZATION-PROTOCOL.md">Optimization protocol ↗</a><a href="source/bulk-projection/">Archived bulk-projection source ↗</a><a href="source/persistent-index/">Archived persistence source ↗</a></p></section>`;
 const d=D['token-pilot'];if(!d)return html;
 const labels={production_style_retokenize:'Retokenize every document',cached_document_sets:'Cached document token sets',postings_only:'Postings scoring only',postings_with_exact_text_hash:'Postings + full ordered-text hash'};
 html+=`<section class="panel"><h3>Lexical component pilot · exact scores, bounded retained memory</h3><p class="subtext">${e(d.documents?.toLocaleString())} canonical SciFact texts × ${e(d.queries)} queries. This component experiment excludes semantic encoding, ledger projection, graph assembly, and response serialization.</p><div class="cards">${card('Exact document-score comparisons',d.document_score_equality_checks?.toLocaleString(),d.all_document_scores_exact?'Every score matched exactly':'Inspect equality checks')}${card('Retained postings cache',(d.memory.total_bytes/1048576).toFixed(2)+' MiB','Python deep estimate; limit '+(d.memory.limit_bytes/1048576).toFixed(0)+' MiB')}${card('Postings build, including hash',sec(d.build_seconds.postings_including_fingerprint),'One ordered cohort; rebuild on change')}</div><div class="table-wrap"><table><thead><tr><th>Lexical method only</th><th class="number">p50</th><th class="number">p95</th><th class="number">300-query total</th></tr></thead><tbody>${Object.entries(d.query_timings).map(([key,row])=>`<tr><td>${e(labels[key]||key)}</td><td class="number">${ms(row.p50_seconds)}</td><td class="number">${ms(row.p95_seconds)}</td><td class="number">${sec(row.total_seconds)}</td></tr>`).join('')}</tbody></table></div><p class="metric-note">Hash-inclusive postings verifies every exact text on each call. Cached token sets measured faster than hash-inclusive postings, but retain ${(d.memory.cached_document_sets_deep_estimate_bytes/1048576).toFixed(2)} MiB under this estimate. Do not omit hash-validation cost when evaluating the proposed cache.</p><div class="notice">${e(d.memory.caveat)}</div>${raw('Exactness, cohort invalidation, memory accounting, and pilot provenance',d)}<div class="report-methods"><a href="token-postings-pilot.json" download>↓ Pilot JSON</a><a href="source/token_postings_pilot.py" download>↓ Executable pilot source</a></div></section>`;
 return html;
}
function ciText(ci){if(!ci)return 'Paired uncertainty results are unavailable.';return `Mean Δ nDCG ${f(ci.mean_difference)}; 95% descriptive bootstrap interval [${f(ci.ci95_low)}, ${f(ci.ci95_high)}]. ${ci.ci95_low<=0&&ci.ci95_high>=0?'The interval includes zero; do not call this a demonstrated gain.':'The interval excludes zero in this query resampling; this is not cross-domain proof.'}`;}
function indexView(){const d=D.index;if(!d)return pending('Production index experiment','index-results.json');const phases=Object.entries(d.phases||{});return heading('Fix the repeated work before changing the ranking.','Production SQLite vector persistence and exact cosine scoring, tested on the complete SciFact corpus. Cold fill, warm queries, and reopen behavior are distinct measurements.','index-results.json')+`<div class="cards">${card('Indexed documents',d.indexed_count?.toLocaleString(),'Same SciFact evidence corpus')}${card('Test queries',d.test_query_count,'Ranking preservation is checked separately')}${card('Compared queries',d.preservation?.compared_queries??'See checks','No inferred correctness from latency alone')}</div><section class="panel"><h3>Cold fill and warm retrieval, reported separately</h3><div class="table-wrap"><table><thead><tr><th>Phase</th><th class="number">Cold first query</th><th class="number">Warm p50</th><th class="number">Warm p95</th><th class="number">Vectors before</th><th class="number">Vectors after cold</th></tr></thead><tbody>${phases.map(([phase,row])=>`<tr><td>${e(phase)}</td><td class="number">${sec(row.cold_first_query?.seconds)}</td><td class="number">${ms(row.warm_latency?.p50_seconds)}</td><td class="number">${ms(row.warm_latency?.p95_seconds)}</td><td class="number">${e(row.vector_rows_before??'—')}</td><td class="number">${e(row.vector_rows_after_cold??'—')}</td></tr>`).join('')}</tbody></table></div><p class="metric-note">Warm scoring excludes the first query’s index fill. Reopened storage must reuse persisted vectors without exposing future evidence. Shared CPU load affects timing.</p></section><section class="panel"><h3>Ranking preservation and actual retrieval quality</h3>${table(phases.map(([n,row])=>({name:n,metrics:row.metrics})),['ndcg@10','recall@10','mrr@10','hit@1'])}${raw('Exact preservation checks',d.preservation)}</section><div class="notice"><strong>Do not turn the old two-query stock pilot into a precise speedup claim.</strong> Its first sample included model initialization; the v1 full run also used a benchmark-only document-cache adaptation. Compare actual configurations and measured stages.</div><section class="panel"><h3>Implementation and measurement evidence</h3>${raw('Index run protocol and implementation',d)}<a href="INDEX-PROTOCOL.md">Read the production-index protocol ↗</a></section>`;}
function crossView(){const d=D['cross-domain'];if(!d)return pending('Cross-domain model comparison','cross-domain-results.json');const available=Object.keys(d.datasets||{});if(!available.includes(dataset))dataset=available[0];const part=d.datasets[dataset],rows=Object.entries(part.systems).map(([n,row])=>({name:n,...row})),paired=part.paired_bootstrap_vs_minilm_hybrid;return heading('Does the model improvement survive a different domain?','Full-corpus public retrieval with fixed BM25, MiniLM, BGE, and reciprocal-rank fusion. Each dataset is shown independently; preprocessing and latency differ from the production Store track.','cross-domain-results.json')+`<div class="dataset-control"><label for="dataset">Evaluation dataset</label><select id="dataset">${available.map(n=>`<option value="${e(n)}"${n===dataset?' selected':''}>${e(n.toUpperCase())}</option>`).join('')}</select></div><div class="cards">${card('Documents in selected corpus',part.corpus_count?.toLocaleString(),'Full corpus, not a selected sample')}${card('Public test queries',part.test_query_count,'Official test relevance judgments')}${card('Judged relevant pairs',part.qrel_pairs,'Relevance is not factual correctness')}</div><section class="panel"><h3>nDCG@10 within ${e(dataset.toUpperCase())}</h3><div style="margin-top:22px">${bars(rows,'ndcg@10')}</div>${table(rows,['ndcg@10','recall@10','mrr@10'])}</section><section class="panel"><h3>Paired difference from MiniLM hybrid</h3><p class="subtext">Query bootstrap per dataset. An interval crossing zero is not evidence of a decisive gain.</p><div class="table-wrap"><table><thead><tr><th>Comparator</th><th class="number">Mean Δ nDCG</th><th class="number">95% interval</th></tr></thead><tbody>${Object.entries(paired?.comparisons||{}).map(([n,row])=>{const ci=row['ndcg@10'];return `<tr><td>${e(name(n))}</td><td class="number">${f(ci?.mean_difference)}</td><td class="number">[${f(ci?.ci95_low)}, ${f(ci?.ci95_high)}]</td></tr>`;}).join('')}</tbody></table></div></section><div class="notice"><strong>Text and runtime protocols differ from the production track.</strong> Cross-domain documents use title + abstract/text, not v1’s canonical assertion wrapper. Absolute scores must not be treated as a same-input v1 comparison.  ${e(d.protocol?.dense_latency_scope)}. ${e(d.protocol?.hybrid_latency_scope)}. Query embedding and indexing are reported separately. Model pretraining overlap with evaluation data was not independently audited.</div><section class="panel"><h3>Local warm ranking cost</h3><div class="table-wrap"><table><thead><tr><th>Method</th><th class="number">p50</th><th class="number">p95</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${e(name(row.name))}</td><td class="number">${ms(row.latency?.p50_seconds)}</td><td class="number">${ms(row.latency?.p95_seconds)}</td></tr>`).join('')}</tbody></table></div>${raw('Corpus, model, indexing, and protocol metadata',{archive:part.archive,index:part.index,protocol:d.protocol,models:d.models,runtime:d.runtime})}</section><section class="panel"><h3>Equal-weight averages do not replace domain results</h3>${table(Object.entries(d.macro_average_equal_weight_per_dataset||{}).map(([n,m])=>({name:n,metrics:m})),['ndcg@10','recall@10','mrr@10'])}<p class="metric-note">Each dataset receives equal weight. This is a descriptive summary of these corpora, not a guarantee on your documents.</p></section>`;}
function ranking(ids,gold,labels){return ids.length?`<ol>${ids.map(id=>`<li class="${gold.includes(id)?'relevant':''}"><strong>${e(id)}</strong>${gold.includes(id)?'<span class="gold-tag">GOLD</span>':''}${labels?.[id]?`<small>${e(labels[id])}</small>`:''}</li>`).join('')}</ol>`:'<p class="subtext">No candidates retained.</p>';}
function rerankView(){const d=D.rerank;if(!d)return pending('Cross-encoder reranking','rerank-results.json');const rows=Object.entries(d.methods).map(([n,row])=>({name:n,...row}));return heading('Does a second reader improve the candidate order?',`A fixed top-${d.parameters?.candidate_k??'recorded'} RRF pool, reranked with ${d.parameters?.model??'the recorded local cross-encoder'}. Runtime: ${d.parameters?.runtime??'not recorded'}. This experiment is not deployed in the product.`,'rerank-results.json')+`<div class="cards">${card('SciFact test queries',d.query_count,'Complete recorded evaluation')}${card('Candidate depth',d.parameters?.candidate_k??'Not recorded','Fixed before test judgments')}${card('Measured methods',rows.length,'First-stage baseline and reranked output')}</div><div class="notice info">${e(ciText(d.paired_ndcg_difference))}</div><section class="panel"><h3>Accuracy and candidate-pool limits</h3><div style="margin-top:22px">${bars(rows,'ndcg@10')}</div>${table(rows,['ndcg@10','recall@10','mrr@10','hit@1'])}<p class="metric-note">A reranker cannot recover evidence missing from the first-stage candidate pool. Cross-encoder logits are relevance scores, not truth confidence.</p></section><section class="panel"><h3>Added latency is part of the result</h3><div class="table-wrap"><table><thead><tr><th>Pipeline</th><th class="number">p50</th><th class="number">p95</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${e(name(row.name))}</td><td class="number">${ms(row.latency?.p50_seconds)}</td><td class="number">${ms(row.latency?.p95_seconds)}</td></tr>`).join('')}</tbody></table></div><p class="metric-note">Fresh query encoding and warm document vectors. Runtime: ${e(d.parameters?.runtime??'not recorded')}; model artifact / precision: ${e(d.parameters?.model_file??'not recorded')}; batch size: ${e(d.parameters?.batch_size??'not recorded')}. Stopped timing pilots did not become an accuracy comparison.</p></section><section class="panel"><h3>Largest observed losses and gains</h3><p class="subtext">Deterministically selected by per-query nDCG difference. Losses appear first; both sides use actual top-10 IDs.</p>${D.rerank_examples.map(row=>`<details class="case"><summary><div class="case-text">${e(row.query)}<small>${e(row.id)} · ${row.delta<0?'Reranker loss':'Reranker gain'}</small></div><span class="case-delta">Δ ${f(row.delta,3)}</span></summary><div class="case-body"><div class="case-meta">Gold: ${e(row.gold.join(', '))}</div><div class="rankings"><div class="ranking"><h4>Before reranking · nDCG ${f(row.before_metrics['ndcg@10'])}</h4>${ranking(row.before,row.gold,D.rerank_titles)}</div><div class="ranking"><h4>After reranking · nDCG ${f(row.after_metrics['ndcg@10'])}</h4>${ranking(row.after,row.gold,D.rerank_titles)}</div></div></div></details>`).join('')||'<p class="subtext">No compact failure examples are available; inspect the raw result JSON.</p>'}</section><section class="panel"><h3>Limits and reproducibility</h3><ul class="caveats" style="margin-top:15px">${(d.limitations||[]).map(item=>`<li>${e(item)}</li>`).join('')}</ul>${raw('Protocol, hashes, and model configuration',d)}</section>`;}
function temporalView(){const d=D.temporal;if(!d)return pending('Held-out temporal and abstention experiment','temporal-results.json');const rows=Object.entries(d.systems).map(([n,row])=>({name:n,metrics:row[mode][split]}));const chrono=d.systems['Chronoverse actual Store'],before=chrono.non_gated.test,after=chrono.gated.test;return heading('Return less unrelated context, without hiding the misses.','Harder manually authored temporal scenarios, disjoint entity names and scenario families, and an abstention gate calibrated only on DEV. No gate is deployed to the app.','temporal-results.json')+`<div class="cards">${card('Calibration / held-out questions',`${d.dev_queries} / ${d.test_queries}`,'Disjoint entities and scenario families')}${card('Held-out answerable / empty',`${after.query_count} / ${after.empty_gold_queries}`,'Gold is fixed by scenario design')}${card('Fixture assertions / events',`${d.assertions} / ${d.events}`,'Chained history, paraphrases, late evidence')}</div><div class="notice"><strong>Precision improves by trading away some relevant evidence.</strong> Store TEST precision changes ${p(before.micro_precision)} → ${p(after.micro_precision)}, but recall changes ${p(before.micro_recall)} → ${p(after.micro_recall)} and false abstention reaches ${p(after.false_abstention_rate)}. nDCG changes ${f(before['ndcg@10'])} → ${f(after['ndcg@10'])}. These losses are part of the result.</div><div class="result-toggle" aria-label="Dataset split"><button data-split="test" class="${split==='test'?'active':''}">Held-out TEST</button><button data-split="dev" class="${split==='dev'?'active':''}">Calibration DEV</button></div><div class="result-toggle" aria-label="Abstention mode"><button data-mode="gated" class="${mode==='gated'?'active':''}">Frozen DEV gate</button><button data-mode="non_gated" class="${mode==='non_gated'?'active':''}">No gate · baseline</button></div><section class="panel"><h3>${split==='test'?'Held-out test':'Development calibration'} · ${mode==='gated'?'selective retrieval':'ungated retrieval'}</h3><p class="subtext">Micro precision counts irrelevant returned records, including records returned for empty-gold questions. Recall counts all relevant supports, including multi-gold conflicts.</p><div class="precision-chart">${bars(rows,'micro_precision')}</div>${table(rows,['micro_precision','micro_recall','coverage','false_abstention_rate','empty_gold_abstention_rate'],{micro_precision:'Precision ↑',micro_recall:'Recall ↑',coverage:'All-query coverage',false_abstention_rate:'False abstention ↓',empty_gold_abstention_rate:'Empty-gold abstention ↑'})}${table(rows,['ndcg@10','hit@1','exact_set_rate','conflict_complete_rate'],{exact_set_rate:'Exact set ↑',conflict_complete_rate:'All conflict supports retained ↑'})}<p class="metric-note">Higher coverage is not automatically better: answering an empty target with unrelated context increases coverage. Abstaining on an answerable query is a false abstention. Compare the measures together.</p></section><section class="panel"><h3>The calibration rule was frozen before reporting TEST</h3><p class="subtext">The gate keeps candidate order. Absolute MiniLM cosine and distance from the best candidate filter each method’s top-10 pool. The gated BM25 condition therefore adds dense semantic signals; it is not native BM25. Cosine is not a truth probability.</p><div class="table-wrap gate-table"><table><thead><tr><th>Retriever</th><th class="number">Absolute cosine</th><th class="number">Relative margin</th><th>DEV coverage constraint</th></tr></thead><tbody>${Object.entries(d.systems).map(([n,row])=>`<tr><td>${e(n)}</td><td class="number">${f(row.frozen_gate.absolute_cosine,2)}</td><td class="number">${f(row.frozen_gate.relative_margin,2)}</td><td>${row.dev_coverage_constraint_met?'Met':'Not met; inspect fallback'}</td></tr>`).join('')}</tbody></table></div>${raw('Predeclared grid and selection objective',d.gate_protocol)}</section><section class="panel"><h3>Held-out failure inspection</h3><p class="subtext">Actual Store output before and after the frozen gate. Examples are selected by loss/abstention category, not by favorable outcomes. Green marks manually specified gold.</p>${D.temporal_examples.map(row=>`<details class="case"><summary><div class="case-text">${e(row.query)}<small>${e(row.id)} · ${e(row.kind)} · ${e(row.family)}</small></div></summary><div class="case-body"><div class="case-meta"><strong>Gold:</strong> ${row.gold_assertion_ids.length?e(row.gold_assertion_ids.join(', ')):'∅ — no target answer'}<br/><strong>Rationale:</strong> ${e(row.rationale)}<br/><strong>Scope:</strong> ${e(JSON.stringify(row.scope))}</div><div class="rankings"><div class="ranking"><h4>Ungated Store</h4>${ranking(row.before,row.gold_assertion_ids,D.temporal_record_labels)}</div><div class="ranking"><h4>Frozen DEV gate</h4>${ranking(row.after,row.gold_assertion_ids,D.temporal_record_labels)}</div></div></div></details>`).join('')}</section><section class="panel"><h3>Stronger than v1, still a synthetic diagnostic</h3><ul class="caveats" style="margin-top:15px">${(d.limitations||[]).map(item=>`<li>${e(item)}</li>`).join('')}<li>Scenario families and entity names are held out, but vocabulary and authoring conventions remain shared. No independently authored public temporal QA set was tested.</li><li>No explicit multi-hop benchmark was added after the fixture was frozen. No graph-superiority inference follows from these results.</li></ul>${raw('Split identities, scenario families, implementation hashes, and protocol',{entity_splits:d.entity_splits,scenario_families:d.scenario_families,protocol:d.protocol,fixture_sha256:d.fixture_sha256,source_sha256:d.source_sha256,model:d.model,versions:d.versions})}</section>`;}
function footerLinks(){return `<section class="panel"><h3>Artifacts and methods</h3><div class="report-methods"><a href="README.md">Interpretation & reproduction ↗</a><a href="EXPERIMENT-DESIGN.md">Predeclared experiment design ↗</a><a href="API-OPTIONS.md">Optional API research paths ↗</a><a href="INDEX-PROTOCOL.md">Index protocol ↗</a><a href="../benchmarks/index.html">Earlier v1 experiments ↗</a></div><div class="source-grid">${['index','cross-domain','rerank','temporal'].filter(n=>D[n]).map(n=>`<a href="${n}-results.json" download>${e(n)} raw JSON</a>`).join('')}<a href="temporal-fixture.json" download>Frozen temporal-v2 fixture</a></div><p class="subtext">Only completed result files are summarized here. Raw artifacts retain all rankings and calibration detail. This report embeds compact examples and loads no CDN or remote script.</p>${raw('Input artifact SHA-256',D.hashes)}</section>`;}
function render(){document.querySelectorAll('[data-track]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.track===track)));$('content').innerHTML=(track==='index'?indexView()+optimizationView():track==='cross-domain'?crossView():track==='rerank'?rerankView():temporalView())+footerLinks();if($('dataset'))$('dataset').addEventListener('change',ev=>{dataset=ev.target.value;render();});document.querySelectorAll('[data-split]').forEach(button=>button.addEventListener('click',()=>{split=button.dataset.split;render();}));document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;render();}));}
document.querySelectorAll('[data-track]').forEach(button=>button.addEventListener('click',()=>{track=button.dataset.track;render();}));
$('status').innerHTML=['index','cross-domain','rerank','temporal'].map(n=>`<span class="${D[n]?'':'pending-status'}">${e(n)} · ${D[n]?'recorded':'pending'}</span>`).join('');render();
'''


def render(data):
    payload=json.dumps(data,ensure_ascii=False,sort_keys=True,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chronoverse · Experiment round two</title><style>'+CSS+EXTRA_CSS+'</style></head><body><header><div><a class="brand" href="#">chronoverse<span>EXPERIMENT ROUND TWO</span></a><span class="local"><i class="dot"></i> Measured locally · no paid inference</span></div></header><main><section class="intro"><div class="eyebrow">FROM A PROMISING DEMO TO A HARDER TEST</div><h1>Improve the system.<br>Keep the counterevidence.</h1><p>Separate four questions: persistence and latency, transfer across domains, a second-stage reranker, and selective retrieval under harder temporal conditions. Every improvement must carry its cost and its failure cases.</p><div id="status" class="track-status"></div></section><nav class="tabs" role="tablist" aria-label="Experiment track"><button data-track="index" role="tab" aria-selected="true">01 · Production index</button><button data-track="cross-domain" role="tab" aria-selected="false">02 · Cross-domain models</button><button data-track="rerank" role="tab" aria-selected="false">03 · Reranking</button><button data-track="temporal" role="tab" aria-selected="false">04 · Temporal + abstention</button></nav><div id="content" role="tabpanel" aria-label="Selected experiment results"></div><noscript><div class="notice">Enable JavaScript for interactive comparisons or open the local result JSON files.</div></noscript><footer class="footer"><span>Precision, recall, coverage, and latency answer different questions.</span><span>No cross-track latency leaderboard. No test-label-driven deployment.</span></footer></main><script type="application/json" id="data">'+payload+'</script><script>'+JS+'</script></body></html>\n'


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--input-dir',type=Path,default=ROOT/'docs/benchmarks-v2');parser.add_argument('--output',type=Path,default=ROOT/'docs/benchmarks-v2/index.html');args=parser.parse_args()
    data=collect(args.input_dir);document=render(data);args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(document)
    fixture=ROOT/'benchmarks/data/temporal-v2.json'
    if fixture.exists():(args.output.parent/'temporal-fixture.json').write_bytes(fixture.read_bytes())
    pilot=ROOT/'benchmarks/token_postings_pilot.py'
    if pilot.exists():
        source=args.output.parent/'source';source.mkdir(exist_ok=True)
        (source/pilot.name).write_bytes(pilot.read_bytes())
    print(json.dumps({'output':str(args.output),'bytes':len(document.encode()),'completed_tracks':[name for name in ('index','cross-domain','rerank','temporal') if data[name]],'sha256':hashlib.sha256(document.encode()).hexdigest()}))


if __name__=='__main__':main()
